@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
  + Manufacturer : string
  + CountryOfManufacture : string
}

class VATRate {
  + CountryCode : string
  + Rate : double
  + Currency : string
  + EuroConversionRate : double
}

class Representative {
  + FirstName : string
  + LastName : string
  + Ssn : int
  + TelephoneNumber : string
  + EmailAddress : string
  + CountriesRepresented : Country[]
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
  + CountriesReselling : Country[]
}

class Order {
  + OrderId : int
  + Product : Product
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

class Country {
  + Code : string
  + Name : string
}

Representative "1" -- "*" Country : represents
Product "1" -- "*" VATRate : has_vat_rate
Customer "1..*" Order : places

@enduml

